session_start();require_once "config/db.php";if(!isset($_SESSION['user_id'])){header("Location: login.php");exit;}$id=$_SESSION['user_id'];$s=$conn->prepare("SELECT * FROM users WHERE user_id=?");$s->bind_param("i",$id);$s->execute();$u=$s->get_result()->fetch_assoc();$msg="";
if($_SERVER["REQUEST_METHOD"]==="POST"){$a=trim($_POST['address']);$city=trim($_POST['city']);$s=$conn->prepare("UPDATE users SET address=?,city=? WHERE user_id=?");$s->bind_param("ssi",$a,$city,$id);$s->execute();$msg="Profile updated successfully."; $u['address']=$a;$u['city']=$city;}
?>
<?php include "includes/header.php";?><main class="section"><div class="container"><div class="form-card"><h2>My Profile</h2><?php if($msg):?><div class="alert success"><?=$msg?></div><?php endif;?><div class="form-grid"><div class="field"><label>First Name</label><input value="<?=htmlspecialchars($u['first_name'])?>" disabled></div><div class="field"><label>Last Name</label><input value="<?=htmlspecialchars($u['last_name'])?>" disabled></div><div class="field"><label>Email</label><input value="<?=htmlspecialchars($u['email'])?>" disabled></div><div class="field"><label>Phone</label><input value="<?=htmlspecialchars($u['phone'])?>" disabled></div></div><br><form method="post"><div class="field"><label>Address</label><input name="address" value="<?=htmlspecialchars($u['address'])?>" required></div><br><div class="field"><label>City</label><input name="city" value="<?=htmlspecialchars($u['city'])?>" required></div><br><button class="btn btn-primary">Save Changes</button></form></div></div></main><?php include "includes/footer.php";?>